/**
 * exportar-resultados-pdf.js
 * Generador de reportes PDF vectoriales estilo Excel con identidad institucional FEDEMOTO.
 * Compatible con resultados de válidas individuales y clasificaciones generales acumuladas.
 */

(function () {
    'use strict';

    const FEDEMOTO_LOGO_BASE64 = 'data:image/png;base64,';

    // Determinar la ruta base hacia la raíz del repositorio
    function getBasePath() {
        const scripts = document.getElementsByTagName('script');
        for (let i = 0; i < scripts.length; i++) {
            const src = scripts[i].getAttribute('src');
            if (src && src.includes('exportar-resultados-pdf.js')) {
                const match = src.match(/^(\.\.\/)+/);
                if (match) return match[0];
                if (src.startsWith('./') || src === 'exportar-resultados-pdf.js') return './';
            }
            if (src && src.includes('load-menu.js')) {
                const match = src.match(/^(\.\.\/)+/);
                if (match) return match[0];
                if (src.startsWith('./') || src === 'load-menu.js') return './';
            }
        }
        // Fallback según pathname
        const parts = decodeURIComponent(window.location.pathname)
            .split('/')
            .filter(p => p && !p.endsWith('.html'));
        return parts.length === 0 ? './' : '../'.repeat(parts.length);
    }

    // Cargar librerías jsPDF y AutoTable si no están en memoria
    function loadJSPDFDependencies() {
        return new Promise((resolve, reject) => {
            if (window.jspdf && window.jspdf.jsPDF) {
                const testDoc = new window.jspdf.jsPDF();
                if (typeof testDoc.autoTable === 'function') {
                    return resolve(window.jspdf.jsPDF);
                }
            }

            const basePath = getBasePath();

            function loadScript(src, fallbackSrc) {
                return new Promise((res, rej) => {
                    const script = document.createElement('script');
                    script.src = src;
                    script.onload = () => res();
                    script.onerror = () => {
                        if (fallbackSrc) {
                            console.warn('Fallo al cargar', src, '- reintentando con fallback', fallbackSrc);
                            const fallbackScript = document.createElement('script');
                            fallbackScript.src = fallbackSrc;
                            fallbackScript.onload = () => res();
                            fallbackScript.onerror = rej;
                            document.head.appendChild(fallbackScript);
                        } else {
                            rej(new Error('No se pudo cargar: ' + src));
                        }
                    };
                    document.head.appendChild(script);
                });
            }

            loadScript(
                basePath + 'lib/jspdf.umd.min.js',
                'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'
            )
                .then(() => {
                    return loadScript(
                        basePath + 'lib/jspdf.plugin.autotable.min.js',
                        'https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js'
                    );
                })
                .then(() => {
                    if (window.jspdf && window.jspdf.applyPlugin && window.jspdf.jsPDF) {
                        try {
                            window.jspdf.applyPlugin(window.jspdf.jsPDF);
                        } catch (e) {
                            // Ignorar si ya fue aplicado
                        }
                    }
                    resolve(window.jspdf ? window.jspdf.jsPDF : window.jsPDF);
                })
                .catch(err => {
                    console.error('Error cargando dependencias PDF:', err);
                    reject(err);
                });
        });
    }

    // Extraer texto limpio de una celda ignorando botones/iconos
    function getCleanCellText(cell) {
        if (!cell) return '';
        const clone = cell.cloneNode(true);
        clone.querySelectorAll('button, svg, script, style, .info-btn, .comentario-btn, .btn-vuelta-a-vuelta').forEach(el => el.remove());
        return clone.textContent.replace(/\s+/g, ' ').trim();
    }

    // Encabezado institucional en cada página
    function drawPageHeader(doc, title, subtitle, dateStr) {
        const pageWidth = doc.internal.pageSize.getWidth();

        // Logo FEDEMOTO
        try {
            doc.addImage(FEDEMOTO_LOGO_BASE64, 'PNG', 12, 7, 24, 15);
        } catch (e) {
            console.warn('No se pudo agregar logo:', e);
        }

        // Títulos
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(11.5);
        doc.setTextColor(18, 62, 146); // Azul institucional #123E92
        doc.text('FEDERACIÓN COLOMBIANA DE MOTOCICLISMO', 40, 12);

        doc.setFont('helvetica', 'bold');
        doc.setFontSize(9.5);
        doc.setTextColor(31, 41, 55); // #1F2937
        const cleanTitle = (title || 'RESULTADOS').toUpperCase();
        doc.text(cleanTitle, 40, 16.5);

        doc.setFont('helvetica', 'normal');
        doc.setFontSize(8);
        doc.setTextColor(107, 114, 128); // #6B7280
        const subText = (subtitle ? subtitle + ' — ' : '') + 'Informe Oficial generado el: ' + dateStr;
        doc.text(subText, 40, 20.5);

        // Barra decorativa bicromática: Azul y Amarillo
        doc.setDrawColor(18, 62, 146);
        doc.setLineWidth(0.7);
        doc.line(12, 23.5, pageWidth - 12, 23.5);

        doc.setDrawColor(247, 195, 29);
        doc.setLineWidth(0.7);
        doc.line(12, 24.3, pageWidth - 12, 24.3);
    }

    // Pie de página con numeración y leyendas
    function drawPageFooters(doc) {
        const pageCount = doc.internal.getNumberOfPages();
        const pageWidth = doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.getHeight();

        for (let i = 1; i <= pageCount; i++) {
            doc.setPage(i);
            doc.setDrawColor(229, 231, 235);
            doc.setLineWidth(0.3);
            doc.line(12, pageHeight - 11, pageWidth - 12, pageHeight - 11);

            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7.5);
            doc.setTextColor(107, 114, 128);
            doc.text('FEDEMOTO — Documento Oficial de Resultados | Federación Colombiana de Motociclismo', 12, pageHeight - 7);
            doc.text('Página ' + i + ' de ' + pageCount, pageWidth - 12, pageHeight - 7, { align: 'right' });
        }
    }

    // Configurar estilos de columnas automáticos tipo Excel
    function getExcelColumnStyles(headers) {
        const styles = {};
        headers.forEach((h, idx) => {
            const hLow = (h || '').toLowerCase().trim();
            if (hLow === 'pos.' || hLow === 'pos') {
                styles[idx] = { halign: 'center', fontStyle: 'bold', cellWidth: 12 };
            } else if (hLow === 'n°' || hLow === 'n' || hLow === 'num' || hLow === 'no.') {
                styles[idx] = { halign: 'center', fontStyle: 'bold', cellWidth: 14 };
            } else if (hLow.includes('nombre') || hLow.includes('piloto')) {
                styles[idx] = { halign: 'left', fontStyle: 'bold' };
            } else if (hLow === 'liga') {
                styles[idx] = { halign: 'left', cellWidth: 26 };
            } else if (hLow === 'club') {
                styles[idx] = { halign: 'left', cellWidth: 38 };
            } else if (hLow === 'moto') {
                styles[idx] = { halign: 'left', cellWidth: 22 };
            } else if (hLow.startsWith('r') && hLow.endsWith('.')) {
                styles[idx] = { halign: 'center', cellWidth: 13 };
            } else if (['i', 'ii', 'iii', 'iv', 'v', 'vi', 'vii', 'viii', 'ix', 'x'].includes(hLow)) {
                styles[idx] = { halign: 'center', cellWidth: 13 };
            } else if (hLow.includes('total')) {
                styles[idx] = { halign: 'center', fontStyle: 'bold', textColor: [18, 62, 146], cellWidth: 18 };
            } else if (hLow.includes('bono')) {
                styles[idx] = { halign: 'center', fontStyle: 'bold', cellWidth: 18 };
            } else if (hLow.includes('dif')) {
                styles[idx] = { halign: 'center', cellWidth: 18 };
            } else if (hLow.includes('tiempo') || hLow.includes('tm')) {
                styles[idx] = { halign: 'center', cellWidth: 20 };
            } else if (hLow.includes('vuelta')) {
                styles[idx] = { halign: 'center', cellWidth: 15 };
            } else if (hLow.includes('puntos')) {
                styles[idx] = { halign: 'center', cellWidth: 15 };
            } else {
                styles[idx] = { halign: 'center' };
            }
        });
        return styles;
    }

    // Configuración base de AutoTable estilo Excel
    function getExcelTableConfig(head, body, startY, extraOptions) {
        const colStyles = getExcelColumnStyles(head[0] || []);
        return Object.assign({
            startY: startY,
            margin: { left: 12, right: 12, top: 27, bottom: 14 },
            head: head,
            body: body,
            theme: 'grid',
            styles: {
                font: 'helvetica',
                fontSize: 7.5,
                cellPadding: 2,
                lineColor: [210, 215, 220], // Bordes grises finos tipo Excel
                lineWidth: 0.1,
                textColor: [17, 24, 39],
                valign: 'middle'
            },
            headStyles: {
                fillColor: [18, 62, 146], // Azul Fedemoto
                textColor: [255, 255, 255],
                fontStyle: 'bold',
                fontSize: 8,
                halign: 'center',
                lineColor: [14, 50, 118],
                lineWidth: 0.2
            },
            alternateRowStyles: {
                fillColor: [248, 249, 250] // Cebra suave
            },
            columnStyles: colStyles,
            didParseCell: function (data) {
                if (data.section === 'body') {
                    // Resaltado elegante de los 3 primeros lugares
                    const isPos1 = data.row.raw._isPos1;
                    const isPos2 = data.row.raw._isPos2;
                    const isPos3 = data.row.raw._isPos3;
                    if (isPos1) {
                        data.cell.styles.fillColor = [254, 243, 199]; // Oro suave #FEF3C7
                    } else if (isPos2) {
                        data.cell.styles.fillColor = [243, 244, 246]; // Plata suave #F3F4F6
                    } else if (isPos3) {
                        data.cell.styles.fillColor = [255, 237, 213]; // Bronce suave #FFEDD5
                    }
                }
            }
        }, extraOptions || {});
    }

    // Extraer datos de un elemento table del DOM
    function extractTableData(tableEl) {
        if (!tableEl) return null;
        const headRow = [];
        const ths = tableEl.querySelectorAll('thead th');
        ths.forEach(th => headRow.push(getCleanCellText(th)));

        const bodyRows = [];
        const trs = tableEl.querySelectorAll('tbody tr');
        trs.forEach(tr => {
            const rowData = [];
            const tds = tr.querySelectorAll('td');
            if (tds.length === 0) return;
            tds.forEach(td => rowData.push(getCleanCellText(td)));

            // Anotar metadatos de podio
            rowData._isPos1 = tr.classList.contains('pos-1');
            rowData._isPos2 = tr.classList.contains('pos-2');
            rowData._isPos3 = tr.classList.contains('pos-3');
            bodyRows.push(rowData);
        });

        return { head: [headRow], body: bodyRows };
    }

    // ─────────────────────────────────────────────────────────────
    // 1. EXPORTADOR PARA VÁLIDAS INDIVIDUALES
    // ─────────────────────────────────────────────────────────────
    window.exportarValidaPDF = async function (options) {
        options = options || {};
        const selectedIds = options.selectedCategories || [];
        const scope = options.scope || 'final'; // 'final' o 'all'

        const jsPDF = await loadJSPDFDependencies();
        const doc = new jsPDF({ orientation: 'landscape', format: 'a4', unit: 'mm' });

        const headerH1 = document.querySelector('.container > header h1')?.textContent.trim() || 'Resultados de Válida';
        const headerP = document.querySelector('.container > header p')?.textContent.trim() || '';
        const todayStr = new Date().toLocaleDateString('es-CO', { day: '2-digit', month: '2-digit', year: 'numeric' });

        let allSections = Array.from(document.querySelectorAll('.categoria-section'));
        if (selectedIds.length > 0) {
            allSections = allSections.filter(s => selectedIds.includes(s.getAttribute('data-categoria-id')));
        }

        if (allSections.length === 0) {
            alert('No hay categorías seleccionadas para exportar.');
            return;
        }

        let isFirstPage = true;

        allSections.forEach(section => {
            if (!isFirstPage) {
                doc.addPage();
            }
            isFirstPage = false;

            drawPageHeader(doc, headerH1, headerP, todayStr);

            const catTitle = section.querySelector('.categoria-header h2')?.textContent.trim() || 'Categoría';

            // Título de la categoría
            doc.setFillColor(18, 62, 146);
            doc.roundedRect(12, 28, 273, 7.5, 1, 1, 'F');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(10.5);
            doc.setTextColor(255, 255, 255);
            doc.text('CATEGORÍA: ' + catTitle.toUpperCase(), 16, 33);

            let currentY = 37.5;

            // Resumen de mejores tiempos (si existe)
            const timesSummary = section.querySelector('.times-summary');
            if (timesSummary) {
                const timesItems = timesSummary.querySelectorAll('p');
                const timeLines = [];
                timesItems.forEach(p => timeLines.push(getCleanCellText(p)));
                if (timeLines.length > 0) {
                    doc.setFont('helvetica', 'normal');
                    doc.setFontSize(7.5);
                    doc.setTextColor(55, 65, 81);
                    timeLines.forEach(line => {
                        doc.text('• ' + line, 14, currentY);
                        currentY += 4;
                    });
                    currentY += 1;
                }
            }

            // 1. Tabla Final
            const finalBlock = section.querySelector('.final-block') || section;
            const finalTable = finalBlock.querySelector('table');
            if (finalTable) {
                const tableData = extractTableData(finalTable);
                if (tableData && tableData.body.length > 0) {
                    doc.setFont('helvetica', 'bold');
                    doc.setFontSize(9);
                    doc.setTextColor(18, 62, 146);
                    doc.text('Clasificación Final de la Válida', 12, currentY + 3.5);
                    currentY += 5;

                    doc.autoTable(getExcelTableConfig(tableData.head, tableData.body, currentY));
                    currentY = doc.lastAutoTable.finalY + 7;
                }
            }

            // 2. Desglose completo de sesiones (si fue solicitado)
            if (scope === 'all') {
                const desgloseBlock = section.querySelector('.desglose-block');
                if (desgloseBlock) {
                    const sessionRows = desgloseBlock.querySelectorAll('.session-title-row');
                    sessionRows.forEach(rowEl => {
                        const sessName = rowEl.querySelector('h3')?.textContent.trim() || 'Sesión';
                        const tableWrapper = rowEl.nextElementSibling;
                        const sessTable = tableWrapper ? tableWrapper.querySelector('table') : null;
                        if (sessTable) {
                            const sessData = extractTableData(sessTable);
                            if (sessData && sessData.body.length > 0) {
                                if (currentY > 165) {
                                    doc.addPage();
                                    drawPageHeader(doc, headerH1, headerP, todayStr);
                                    currentY = 28;
                                }

                                doc.setFont('helvetica', 'bold');
                                doc.setFontSize(8.5);
                                doc.setTextColor(31, 41, 55);
                                doc.text('Desglose: ' + sessName, 12, currentY + 3);
                                currentY += 4.5;

                                doc.autoTable(getExcelTableConfig(sessData.head, sessData.body, currentY));
                                currentY = doc.lastAutoTable.finalY + 6;
                            }
                        }
                    });
                }
            }
        });

        drawPageFooters(doc);

        const safeFilename = ('Resultados_' + headerH1)
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-zA-Z0-9_-]+/g, '_')
            .replace(/^_+|_+$/g, '');
        doc.save(safeFilename + '.pdf');
    };

    // ─────────────────────────────────────────────────────────────
    // 2. EXPORTADOR PARA RESULTADOS GENERALES ACUMULADOS
    // ─────────────────────────────────────────────────────────────
    window.exportarGeneralPDF = async function (options) {
        options = options || {};
        const selectedIds = options.selectedCategories || [];
        const includeLigas = options.includeLigas !== false;

        const jsPDF = await loadJSPDFDependencies();
        const doc = new jsPDF({ orientation: 'landscape', format: 'a4', unit: 'mm' });

        const headerH1 = document.querySelector('.container > header h1')?.textContent.trim() || 'Resultados Generales';
        const headerP = document.querySelector('.container > header p')?.textContent.trim() || '';
        const introMsg = document.querySelector('.intro-message p')?.textContent.trim() || '';
        const todayStr = new Date().toLocaleDateString('es-CO', { day: '2-digit', month: '2-digit', year: 'numeric' });

        let isFirstPage = true;
        let currentY = 28;

        // Resumen de podios por liga
        if (includeLigas) {
            const ligaSummaryTable = document.querySelector('.liga-summary table');
            if (ligaSummaryTable) {
                drawPageHeader(doc, headerH1, headerP, todayStr);
                isFirstPage = false;

                doc.setFillColor(18, 62, 146);
                doc.roundedRect(12, currentY, 273, 7.5, 1, 1, 'F');
                doc.setFont('helvetica', 'bold');
                doc.setFontSize(10.5);
                doc.setTextColor(255, 255, 255);
                doc.text('RESUMEN DE LIGAS (PODIOS)', 16, currentY + 5);
                currentY += 9.5;

                if (introMsg) {
                    doc.setFont('helvetica', 'normal');
                    doc.setFontSize(8);
                    doc.setTextColor(75, 85, 99);
                    doc.text(introMsg, 13, currentY + 1.5);
                    currentY += 5;
                }

                const ligaData = extractTableData(ligaSummaryTable);
                if (ligaData) {
                    doc.autoTable(getExcelTableConfig(ligaData.head, ligaData.body, currentY, {
                        columnStyles: {
                            0: { halign: 'left', fontStyle: 'bold' },
                            1: { halign: 'center', fontStyle: 'bold' },
                            2: { halign: 'center', fontStyle: 'bold' },
                            3: { halign: 'center', fontStyle: 'bold' }
                        }
                    }));
                    currentY = doc.lastAutoTable.finalY + 8;
                }
            }
        }

        // Tablas por Categoría
        let allSections = Array.from(document.querySelectorAll('.categoria-section'));
        if (selectedIds.length > 0) {
            allSections = allSections.filter(s => selectedIds.includes(s.getAttribute('data-categoria-id')));
        }

        allSections.forEach(section => {
            if (!isFirstPage && currentY > 120) {
                doc.addPage();
                currentY = 28;
            }
            if (isFirstPage) {
                drawPageHeader(doc, headerH1, headerP, todayStr);
                isFirstPage = false;
            } else if (currentY === 28) {
                drawPageHeader(doc, headerH1, headerP, todayStr);
            }

            const catTitle = section.querySelector('.categoria-header h2')?.textContent.trim() || 'Categoría';

            doc.setFillColor(18, 62, 146);
            doc.roundedRect(12, currentY, 273, 7.5, 1, 1, 'F');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(10.5);
            doc.setTextColor(255, 255, 255);
            doc.text('CATEGORÍA: ' + catTitle.toUpperCase(), 16, currentY + 5);
            currentY += 9.5;

            const catTable = section.querySelector('table');
            if (catTable) {
                const tableData = extractTableData(catTable);
                if (tableData && tableData.body.length > 0) {
                    doc.autoTable(getExcelTableConfig(tableData.head, tableData.body, currentY));
                    currentY = doc.lastAutoTable.finalY + 8;
                }
            }
        });

        drawPageFooters(doc);

        const safeFilename = ('Resultados_Generales_' + headerH1 + '_' + headerP)
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-zA-Z0-9_-]+/g, '_')
            .replace(/^_+|_+$/g, '');
        doc.save(safeFilename + '.pdf');
    };

    // ─────────────────────────────────────────────────────────────
    // 3. INICIALIZACIÓN AUTOMÁTICA EN LA PÁGINA
    // ─────────────────────────────────────────────────────────────
    function initPDFExportUI() {
        const isGeneral = !!document.querySelector('.liga-summary') ||
            (document.title && document.title.toLowerCase().includes('resultados generales'));
        const isValida = !!document.getElementById('descargarPDF') || !!document.querySelector('.categoria-section .final-block');

        // Caso A: Página de Válida individual
        if (!isGeneral && isValida) {
            setupValidaUI();
        }

        // Caso B: Página de Resultados Generales
        if (isGeneral) {
            setupGeneralUI();
        }
    }

    // Configurar interfaz para Válida Individual
    function setupValidaUI() {
        const btnPDF = document.getElementById('descargarPDF');
        const modal = document.getElementById('modalExportar');
        const modalBtn = document.getElementById('modalExportarBtn');

        if (!btnPDF || !modal || !modalBtn) return;

        // Inyectar selector de alcance si no existe
        if (!document.getElementById('modalScopeBox')) {
            const scopeBox = document.createElement('div');
            scopeBox.id = 'modalScopeBox';
            scopeBox.style.cssText = 'margin-bottom: 16px; padding: 12px 14px; background: #f0f4fc; border-radius: 8px; border-left: 4px solid #123E92;';
            scopeBox.innerHTML = `
                <div style="font-weight: 700; color: #123E92; margin-bottom: 8px; font-size: 0.9em; font-family: sans-serif;">Contenido a incluir en el PDF:</div>
                <div style="display: flex; gap: 16px; flex-wrap: wrap;">
                    <label style="display: inline-flex; align-items: center; gap: 6px; font-size: 0.9em; color: #1f2937; cursor: pointer;">
                        <input type="radio" name="exportScopeOption" value="final" checked>
                        <span><strong>Solo tablas Finales</strong> (Resumen de la válida)</span>
                    </label>
                    <label style="display: inline-flex; align-items: center; gap: 6px; font-size: 0.9em; color: #1f2937; cursor: pointer;">
                        <input type="radio" name="exportScopeOption" value="all">
                        <span><strong>Final + Desglose</strong> (Clasificatoria y Carreras)</span>
                    </label>
                </div>
            `;
            const catContainer = document.getElementById('modalCategorias');
            if (catContainer && catContainer.parentElement) {
                catContainer.parentElement.insertBefore(scopeBox, catContainer);
            }
        }

        // Reemplazar listener del botón Exportar para usar descarga limpia
        const newModalBtn = modalBtn.cloneNode(true);
        modalBtn.parentNode.replaceChild(newModalBtn, modalBtn);

        newModalBtn.addEventListener('click', async function () {
            const selected = [];
            document.querySelectorAll('#modalCategorias input[type="checkbox"]').forEach(cb => {
                if (cb.checked) selected.push(cb.value);
            });

            if (selected.length === 0) {
                alert('Selecciona al menos una categoría para exportar.');
                return;
            }

            const scopeRadio = document.querySelector('input[name="exportScopeOption"]:checked');
            const scope = scopeRadio ? scopeRadio.value : 'final';

            const originalText = newModalBtn.textContent;
            newModalBtn.textContent = '⏳ Generando PDF...';
            newModalBtn.disabled = true;

            try {
                await window.exportarValidaPDF({
                    selectedCategories: selected,
                    scope: scope
                });
            } catch (err) {
                console.error('Error generando PDF de válida:', err);
                alert('Ocurrió un error al generar el PDF: ' + err.message);
            } finally {
                newModalBtn.textContent = originalText;
                newModalBtn.disabled = false;
                modal.classList.remove('open');
            }
        });
    }

    // Configurar interfaz para Resultados Generales
    function setupGeneralUI() {
        // 1. Agregar botón "Exportar a PDF" si no existe
        let btnPDF = document.getElementById('descargarPDFGeneral');
        if (!btnPDF) {
            const toolbar = document.querySelector('.toolbar');
            if (toolbar) {
                toolbar.style.display = 'flex';
                toolbar.style.gap = '15px';
                toolbar.style.alignItems = 'center';
                toolbar.style.flexWrap = 'wrap';

                btnPDF = document.createElement('button');
                btnPDF.id = 'descargarPDFGeneral';
                btnPDF.className = 'btn-pdf';
                btnPDF.type = 'button';
                btnPDF.innerHTML = '📄 Exportar a PDF';
                btnPDF.style.cssText = 'padding: 11px 22px; background: #123E92; color: #fff; border: 0; border-radius: 8px; font-weight: 700; cursor: pointer; white-space: nowrap; font-family: inherit; font-size: 0.95em; transition: all 0.2s;';
                btnPDF.onmouseenter = () => btnPDF.style.background = '#0f3377';
                btnPDF.onmouseleave = () => btnPDF.style.background = '#123E92';

                toolbar.appendChild(btnPDF);
            }
        }

        // 2. Crear modal para Resultados Generales si no existe
        let modal = document.getElementById('modalExportarGeneral');
        if (!modal) {
            const categories = Array.from(document.querySelectorAll('.categoria-section')).map(s => {
                const id = s.getAttribute('data-categoria-id');
                const name = s.querySelector('.categoria-header h2')?.textContent.trim() || id;
                return { id, name };
            });

            const catCheckboxes = categories.map(c => `
                <label style="display: flex; align-items: center; gap: 8px; padding: 6px 10px; background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 6px; cursor: pointer; font-size: 0.9em;">
                    <input type="checkbox" value="${c.id}" checked>
                    <span>${c.name}</span>
                </label>
            `).join('');

            modal = document.createElement('div');
            modal.id = 'modalExportarGeneral';
            modal.className = 'modal-overlay';
            modal.innerHTML = `
                <div class="modal-box" style="background:#fff; border-radius:12px; padding:24px; max-width:680px; width:92%; max-height:85vh; overflow-y:auto; box-shadow:0 20px 60px rgba(0,0,0,0.3);">
                    <h3 style="margin-bottom: 8px; color: #123E92; font-size: 1.5em;">Exportar Resultados Generales a PDF</h3>
                    <p style="margin-bottom: 16px; font-size: 0.95em; color: #4B5563;">Configura las secciones que deseas incluir en el informe PDF:</p>
                    
                    <div style="margin-bottom: 16px; padding: 12px 14px; background: #f0f4fc; border-radius: 8px; border-left: 4px solid #123E92;">
                        <label style="display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: 0.95em; color: #1f2937;">
                            <input type="checkbox" id="modalGeneralIncludeLigas" checked>
                            <span><strong>Incluir tabla de resumen de podios por liga</strong></span>
                        </label>
                    </div>

                    <div style="font-weight: 700; color: #123E92; margin-bottom: 8px; font-size: 0.9em;">Categorías acumuladas:</div>
                    <div id="modalGeneralCategorias" style="display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 8px; margin-bottom: 14px;">
                        ${catCheckboxes}
                    </div>

                    <div style="display: flex; gap: 10px; margin-bottom: 20px;">
                        <button type="button" id="modalGeneralSelectAll" style="background: none; border: 0; color: #123E92; text-decoration: underline; cursor: pointer; font-size: 0.85em; font-weight: 600;">Seleccionar todo</button>
                        <button type="button" id="modalGeneralDeselectAll" style="background: none; border: 0; color: #123E92; text-decoration: underline; cursor: pointer; font-size: 0.85em; font-weight: 600;">Deseleccionar todo</button>
                    </div>

                    <div style="display: flex; justify-content: flex-end; gap: 10px;">
                        <button type="button" id="modalGeneralCancelar" class="modal-btn modal-btn-secondary" style="padding: 10px 18px; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; cursor: pointer;">Cancelar</button>
                        <button type="button" id="modalGeneralExportarBtn" class="modal-btn modal-btn-primary" style="padding: 10px 22px; border: 0; border-radius: 8px; background: #123E92; color: #fff; font-weight: 700; cursor: pointer;">Descargar PDF</button>
                    </div>
                </div>
            `;
            document.body.appendChild(modal);

            document.getElementById('modalGeneralSelectAll').addEventListener('click', () => {
                document.querySelectorAll('#modalGeneralCategorias input').forEach(cb => cb.checked = true);
            });
            document.getElementById('modalGeneralDeselectAll').addEventListener('click', () => {
                document.querySelectorAll('#modalGeneralCategorias input').forEach(cb => cb.checked = false);
            });
            document.getElementById('modalGeneralCancelar').addEventListener('click', () => {
                modal.classList.remove('open');
            });
            modal.addEventListener('click', (e) => {
                if (e.target === modal) modal.classList.remove('open');
            });

            document.getElementById('modalGeneralExportarBtn').addEventListener('click', async function () {
                const selected = [];
                document.querySelectorAll('#modalGeneralCategorias input[type="checkbox"]').forEach(cb => {
                    if (cb.checked) selected.push(cb.value);
                });

                const includeLigas = document.getElementById('modalGeneralIncludeLigas').checked;

                if (selected.length === 0 && !includeLigas) {
                    alert('Selecciona al menos una categoría o incluye el resumen de ligas.');
                    return;
                }

                const btn = this;
                const origText = btn.textContent;
                btn.textContent = '⏳ Generando PDF...';
                btn.disabled = true;

                try {
                    await window.exportarGeneralPDF({
                        selectedCategories: selected,
                        includeLigas: includeLigas
                    });
                } catch (err) {
                    console.error('Error generando PDF general:', err);
                    alert('Ocurrió un error al generar el PDF: ' + err.message);
                } finally {
                    btn.textContent = origText;
                    btn.disabled = false;
                    modal.classList.remove('open');
                }
            });
        }

        if (btnPDF && modal) {
            btnPDF.addEventListener('click', () => {
                modal.classList.add('open');
            });
        }
    }

    // Inicializar cuando el DOM esté listo
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initPDFExportUI);
    } else {
        initPDFExportUI();
    }
})();
